/*
 * A257882  Sequence (a(n)) generated by Rule 1 (in Comments) with a(1) = 2
 *          and d(1) = 2.
 * https://oeis.org/A257882
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   sequence generated by Rule 1 with a(1) = 2 and d(1) = 2
 * Range:     u8 n <= 172, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   hash_idx
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/hash_idx.h"

typedef struct { int64_t key; uint8_t used; } hash_entry;

static inline bool hash_set_find(hash_entry *tbl, size_t cap, int64_t key) {
    size_t i = hash_idx(key, cap);
    while (tbl[i].used) {
        if (tbl[i].key == key) return true;
        i = (i + 1) & (cap - 1);
    }
    return false;
}

static inline void hash_set_insert(hash_entry *tbl, size_t cap, int64_t key) {
    size_t i = hash_idx(key, cap);
    while (tbl[i].used) {
        if (tbl[i].key == key) return;
        i = (i + 1) & (cap - 1);
    }
    tbl[i].key = key;
    tbl[i].used = 1;
}

/* data structures -------------------------------------------------------- */
static seq_t *a_arr  = NULL;
static size_t a_cap  = 0, a_len  = 0;

static int64_t *d_arr = NULL;
static size_t d_cap   = 0, d_len  = 0;

static hash_entry *Aa  = NULL; /* set of a values (int64_t) */
static size_t Aa_cap   = 0;

static hash_entry *Ad  = NULL; /* set of d values (int64_t) */
static size_t Ad_cap   = 0;

static bool initialized = false;

/* helpers --------------------------------------------------------------- */
static void push_a(seq_t val) {
    if (a_len == a_cap) {
        a_cap = (a_cap == 0) ? 128 : a_cap << 1;
        a_arr = (seq_t*)realloc(a_arr, a_cap * sizeof(seq_t));
    }
    a_arr[a_len++] = val;
    hash_set_insert(Aa, Aa_cap, (int64_t)val);
}

static void push_d(int64_t val) {
    if (d_len == d_cap) {
        d_cap = (d_cap == 0) ? 128 : d_cap << 1;
        d_arr = (int64_t*)realloc(d_arr, d_cap * sizeof(int64_t));
    }
    d_arr[d_len++] = val;
    hash_set_insert(Ad, Ad_cap, val);
}

/* initialization --------------------------------------------------------- */
static void init(void) {
    if (initialized) return;

    /* arrays */
    a_cap = 128;
    a_arr = (seq_t*)malloc(a_cap * sizeof(seq_t));
    d_cap = 128;
    d_arr = (int64_t*)malloc(d_cap * sizeof(int64_t));

    /* hash tables: size 2^16 > 10000 guarantees few collisions */
    Aa_cap = 1 << 16;
    Aa = (hash_entry*)calloc(Aa_cap, sizeof(hash_entry));
    Ad_cap = 1 << 16;
    Ad = (hash_entry*)calloc(Ad_cap, sizeof(hash_entry));

    /* seed a(1)=2, d(1)=2 */
    a_arr[0] = 2;
    d_arr[0] = 2;
    a_len = d_len = 1;

    hash_set_insert(Aa, Aa_cap, (int64_t)2);
    hash_set_insert(Ad, Ad_cap, (int64_t)2);

    initialized = true;
}

/* sequence function ------------------------------------------------------ */
seq_t a(idx_t n) {
    if (n == 0) return 0;        /* undefined for n<1, safe fallback */
    init();

    while (a_len < (size_t)n) {
        seq_t cur_a_seq = a_arr[a_len - 1];
        int64_t cur_a = (int64_t)cur_a_seq;

        int64_t lower = (int64_t)1 - cur_a;   /* inclusive lower bound for h < 0 */
        int64_t chosen_h = 0;
        bool found = false;

        /* Step 1: try negative h */
        for (int64_t h = -1; h >= lower; --h) {
            if (!hash_set_find(Ad, Ad_cap, h) &&
                !hash_set_find(Aa, Aa_cap, cur_a + h)) {
                chosen_h = h;
                found = true;
                break;   /* greatest such h found */
            }
        }

        /* Step 2: if no negative h, positive h */
        if (!found) {
            for (int64_t h = 1;; ++h) {
                if (!hash_set_find(Ad, Ad_cap, h) &&
                    !hash_set_find(Aa, Aa_cap, cur_a + h)) {
                    chosen_h = h;
                    break;
                }
            }
        }

        int64_t new_a = cur_a + chosen_h;
        seq_t new_a_seq = (seq_t)new_a;

        push_a(new_a_seq);
        push_d(chosen_h);
    }

    return a_arr[n - 1];
}
